// 	var maxCount int
// 	var count int

// 	for _, v := range nums {
		
// 		if v == 0 { 

// 			if maxCount < count {
// 				maxCount = count
// 			}
				
// 			count = 0
// 			continue
// 		}

// 		count++
// 	}   

// 	if count > maxCount {
// 		maxCount = count
// 	}

// 	return maxCount
// }

func findMaxConsecutiveOnes(nums []int) int {
	maxCount := 0
	count := 0

	for _, v := range nums {
		if v == 1 {
			count++

			if count > maxCount {
				maxCount = count
			}
		} else {
			count = 0
		}
	}

	return maxCount
}

func findMaxConsecutiveOnes(nums []int) int {
	maxCount, count := 0, 0

	for _, v := range nums {
		if v == 0 {
			count = 0
			continue
		}

		count++

		if count > maxCount {
			maxCount = count
		}
	}

	return maxCount
}

